const body = $input.first().json.body || $input.first().json;
const langue_source = (body.langue_source || 'fr').toUpperCase();
const langue_cible  = (body.langue_cible  || 'en').toUpperCase();

const noms_langues = { FR: 'français', EN: 'anglais', AR: 'arabe', PT: 'portugais', ES: 'espagnol' };

return [{ json: {
  texte:          body.texte || body.content || '',
  langue_source:  langue_source,
  langue_cible:   langue_cible,
  nom_source:     noms_langues[langue_source] || langue_source,
  nom_cible:      noms_langues[langue_cible]  || langue_cible,
  type_document:  body.type_document || 'Document officiel',
  demandeur:      body.demandeur || '',
  email_retour:   body.email_retour || 'contact@transferai.ci',
  traduction_id:  'TRD-' + Date.now()
}}];

